package opennox

import (
	"encoding/json"
	"fmt"
	"image"
	"os"
	"testing"

	"github.com/opennox/libs/noximage"
	"github.com/opennox/opennox/v1/common/memmap"
	"github.com/opennox/opennox/v1/legacy"
	"github.com/opennox/opennox/v1/legacy/common/alloc"
)

// Generated by executing the untouched original GAME.EXE instructions. Only
// external C allocators and DirectDraw services were supplied by the oracle;
// the original surface factory itself ran and returned failure for flag 0x40.
type videoOriginalFixture struct {
	OriginalSHA string `json:"original_sha256"`
	Selectors   []struct {
		Flags        uint32 `json:"flags"`
		Initial      uint32 `json:"initial_counter"`
		SoftwareOnly bool   `json:"software_only"`
		Address      uint32 `json:"selected_address"`
		Counter      uint32 `json:"counter"`
	} `json:"selectors"`
	Copies []struct {
		Flags          uint32 `json:"flags"`
		Skip           uint32 `json:"skip"`
		HResult        uint32 `json:"hresult"`
		Initial        uint32 `json:"initial_counter"`
		Width, Height  int
		Counter        uint32   `json:"counter"`
		Swapped        bool     `json:"swapped"`
		Services       []string `json:"services"`
		SoftwareCopied bool     `json:"software_pixels_copied"`
	} `json:"copies"`
	Initializations []struct {
		Flags         uint32 `json:"flags"`
		Borrowed      bool   `json:"borrowed"`
		Result        int    `json:"result"`
		Width, Height int
	} `json:"initializations"`
}

func loadVideoOriginalFixture(t *testing.T) videoOriginalFixture {
	t.Helper()
	data, err := os.ReadFile("testdata/video_backbuffer_original.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture videoOriginalFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if fixture.OriginalSHA != "0040e2c0683b4d73a5fb976e400d5087dca680df2b195c9e27f8edbda2d4974a" || len(fixture.Selectors) != 1566 || len(fixture.Copies) != 432 || len(fixture.Initializations) != 8 {
		t.Fatal("incomplete original video fixture")
	}
	return fixture
}

func isolateVideoBackBuffer(t *testing.T) {
	t.Helper()
	client, buffers, flags, mode := noxClient, noxPixBuffer, nox_video_renderTargetFlags, videoCopyMode
	count, skip, borrowed := memmap.Uint32(0x973A20, 496), memmap.Uint32(0x973A20, 592), memmap.Uint32(0x5D4594, 1193200)
	noxClient = nil
	noxPixBuffer = videoPixelBuffers{}
	*memmap.PtrUint32(0x5D4594, 1193200) = 0
	t.Cleanup(func() {
		*memmap.PtrUint32(0x5D4594, 1193200) = 0
		nox_free_pixbuffers_486110()
		noxClient, noxPixBuffer, nox_video_renderTargetFlags, videoCopyMode = client, buffers, flags, mode
		*memmap.PtrUint32(0x973A20, 496), *memmap.PtrUint32(0x973A20, 592), *memmap.PtrUint32(0x5D4594, 1193200) = count, skip, borrowed
		publishVideoPixBuffer()
	})
}

func TestVideoBackBufferOriginalSelectors(t *testing.T) {
	isolateVideoBackBuffer(t)
	for i, row := range loadVideoOriginalFixture(t).Selectors {
		nox_video_renderTargetFlags = int(row.Flags)
		*memmap.PtrUint32(0x973A20, 496) = row.Initial
		if row.SoftwareOnly {
			nox_video_setBackBufferCopyFunc2_4AD150()
		} else if err := nox_video_setBackBufferCopyFunc_4AD100(); err != nil {
			t.Fatal(err)
		}
		address := map[videoBackBufferCopyMode]uint32{videoCopyLocked: 0x4ad1e0, videoCopyDirect: 0x4ad2a0, videoCopyBlit: 0x4ad180}[videoCopyMode]
		if address != row.Address || memmap.Uint32(0x973A20, 496) != row.Counter {
			t.Fatalf("selector %d: mode=%#x count=%d; want %#x/%d", i, address, memmap.Uint32(0x973A20, 496), row.Address, row.Counter)
		}
	}
}

func TestVideoBackBufferOriginalCopies(t *testing.T) {
	isolateVideoBackBuffer(t)
	for i, row := range loadVideoOriginalFixture(t).Copies {
		nox_free_pixbuffers_486110()
		nox_video_renderTargetFlags = int(row.Flags)
		_ = nox_video_initPixbuffer_486090(image.Pt(row.Width, row.Height))
		if err := nox_video_setBackBufferCopyFunc_4AD100(); err != nil {
			t.Fatal(err)
		}
		*memmap.PtrUint32(0x973A20, 496), *memmap.PtrUint32(0x973A20, 592) = row.Initial, row.Skip
		primary, alternate := noxPixBuffer.img, noxPixBuffer.back.img
		calls := 0
		copyVideoBackBuffer(func(img *noximage.Image16) bool {
			calls++
			if img != primary {
				t.Fatalf("copy %d: wrong presented source", i)
			}
			return row.HResult == 0
		})
		wantCalls := 0
		if len(row.Services) != 0 || row.SoftwareCopied {
			wantCalls = 1
		}
		want := primary
		if row.Swapped {
			want = alternate
		}
		if calls != wantCalls || noxPixBuffer.img != want || memmap.Uint32(0x973A20, 496) != row.Counter {
			t.Fatalf("copy %d: calls=%d swap=%v counter=%d; want %d/%v/%d", i, calls, noxPixBuffer.img != primary, memmap.Uint32(0x973A20, 496), wantCalls, row.Swapped, row.Counter)
		}
		if *legacy.VideoModeRowsC != &noxPixBuffer.rows[0] || noxPixBuffer.rows[row.Height-1] != &want.Row(row.Height - 1)[0] {
			t.Fatalf("copy %d: stale native row table", i)
		}
	}
}

func TestVideoBackBufferOriginalInitializationAndOwnership(t *testing.T) {
	for i, row := range loadVideoOriginalFixture(t).Initializations {
		t.Run(fmt.Sprint(i), func(t *testing.T) {
			isolateVideoBackBuffer(t)
			nox_video_renderTargetFlags = int(row.Flags)
			if row.Borrowed {
				for _, buffer := range []*videoPixelBuffer{&noxPixBuffer.videoPixelBuffer, &noxPixBuffer.back} {
					data, free := alloc.Make([]uint16{}, row.Width*row.Height)
					buffer.img, buffer.free = noximage.NewImage16WithData(data, image.Pt(row.Width, row.Height)), free
				}
				*memmap.PtrUint32(0x5D4594, 1193200) = 1
			}
			err := nox_video_initPixbuffer_486090(image.Pt(row.Width, row.Height))
			if (err == nil) != (row.Result == 1) {
				t.Fatalf("original init result=%d; native error=%v", row.Result, err)
			}
			var frees [4]int
			for j, buffer := range []*videoPixelBuffer{&noxPixBuffer.videoPixelBuffer, &noxPixBuffer.back} {
				if j == 1 && row.Flags&0x40 == 0 {
					continue
				}
				if buffer.img == nil || len(buffer.img.Pix) != row.Width*row.Height || len(buffer.rows) != row.Height {
					t.Fatal("both images need full 16-bit storage and native rows")
				}
				for y, ptr := range buffer.rows {
					if ptr != &buffer.img.Row(y)[0] {
						t.Fatal("incorrect native row stride")
					}
				}
				oldData, oldRows := buffer.free, buffer.freeRows
				buffer.free = func() { frees[2*j]++; oldData() }
				buffer.freeRows = func() { frees[2*j+1]++; oldRows() }
			}
			nox_free_pixbuffers_486110()
			nox_free_pixbuffers_486110()
			for j := 0; j < 2; j++ {
				if j == 1 && row.Flags&0x40 == 0 {
					continue
				}
				wantData := 1
				if row.Borrowed {
					wantData = 0
				}
				if frees[2*j] != wantData || frees[2*j+1] != 1 {
					t.Fatalf("buffer %d: data/row frees=%d/%d", j, frees[2*j], frees[2*j+1])
				}
			}
			if *legacy.VideoModeRowsC != nil {
				t.Fatal("C retained freed rows")
			}
		})
	}
}
